from collections import deque

class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

# DFS Pre-Order (Recursão / Pilha)
def dfs(no):
    if not no: return
    print(no.val)
    dfs(no.left)
    dfs(no.right)

# Busca em BST -> O(log n) se balanceada
def buscar_bst(no, alvo):
    if not no or no.val == alvo: return no
    if alvo < no.val: return buscar_bst(no.left, alvo)
    return buscar_bst(no.right, alvo)

